update wine_archetypes set description = $d$Traditional-method sparkling from Macabeo, Xarel·lo and Parellada, mostly from Penedès: citrus, apple and a light bready note from shorter lees ageing, often with a faintly earthy edge from the native Catalan grapes, dry, with medium to medium(+) acidity and a creamy mousse. Less acidic and less brioche-rich than Champagne.$d$ where name = 'A typical Cava';
