-- Post-state.
do $post$
begin
  if not (exists (select 1 from wine_archetype_aromas where archetype_id = (select id from wine_archetypes where name = 'A typical Margaux') and term_id = (select id from wset_aroma_terms where term = 'violet' and group_name = 'Floral') and kind = 'NOSE' and signature = true)) then raise exception 'post-state: A typical Margaux violet (Floral) NOSE'; end if;
  if not ((select description from wine_archetypes where name = 'A typical Margaux') = $d$Cabernet-led Médoc from thin, gravelly soils: blackcurrant with a violet perfume and cedar, over fine, silky tannin — lighter-framed and more fragrant than Pauillac or Saint-Estèphe. Tobacco and leather come with bottle age.$d$) then raise exception 'post-state: A typical Margaux description'; end if;
  if not ((select coalesce(array_agg(td.name order by td.name), '{}') from wine_archetype_designations d join type_designations td on td.id = d.type_designation_id where d.archetype_id = (select id from wine_archetypes where name = 'A typical Margaux')) = array['Grand Cru Classé']::text[]) then raise exception 'post-state: A typical Margaux designations'; end if;
  if not ((select typical_age_low = 8 and typical_age_high = 25 from wine_archetypes where name = 'A typical Margaux')) then raise exception 'post-state: A typical Margaux age'; end if;
  if not ((select sat -> 'finish' from wine_archetypes where name = 'A typical Margaux') = '["MEDIUM_PLUS","LONG"]'::jsonb) then raise exception 'post-state: A typical Margaux finish'; end if;
  if not ((select sat -> 'alcohol' from wine_archetypes where name = 'A typical Margaux') = '["MEDIUM","HIGH"]'::jsonb) then raise exception 'post-state: A typical Margaux alcohol'; end if;
  if not ((select coalesce(array_agg(td.name order by td.name), '{}') from wine_archetype_designations d join type_designations td on td.id = d.type_designation_id where d.archetype_id = (select id from wine_archetypes where name = 'A typical Saint-Estèphe')) = array['Cru Bourgeois', 'Grand Cru Classé']::text[]) then raise exception 'post-state: A typical Saint-Estèphe designations'; end if;
  if not (exists (select 1 from wine_archetype_aromas where archetype_id = (select id from wine_archetypes where name = 'A typical Pomerol') and term_id = (select id from wset_aroma_terms where term = 'red plum' and group_name = 'Red fruit') and kind = 'NOSE' and signature = false)) then raise exception 'post-state: A typical Pomerol red plum (Red fruit) NOSE'; end if;
  if not (exists (select 1 from wine_archetype_aromas where archetype_id = (select id from wine_archetypes where name = 'A typical Pomerol') and term_id = (select id from wset_aroma_terms where term = 'red plum' and group_name = 'Red fruit') and kind = 'PALATE' and signature = false)) then raise exception 'post-state: A typical Pomerol red plum (Red fruit) PALATE'; end if;
  if not ((select typical_age_low = 1 and typical_age_high = 5 from wine_archetypes where name = 'A typical Chablis')) then raise exception 'post-state: A typical Chablis age'; end if;
  if not (exists (select 1 from wine_archetype_aromas where archetype_id = (select id from wine_archetypes where name = 'A typical Chablis') and term_id = (select id from wset_aroma_terms where term = 'wet stones' and group_name = 'Other') and kind = 'NOSE' and signature = true)) then raise exception 'post-state: A typical Chablis wet stones (Other) NOSE'; end if;
  if not (exists (select 1 from wine_archetype_aromas where archetype_id = (select id from wine_archetypes where name = 'A typical Chablis') and term_id = (select id from wset_aroma_terms where term = 'wet stones' and group_name = 'Other') and kind = 'PALATE' and signature = true)) then raise exception 'post-state: A typical Chablis wet stones (Other) PALATE'; end if;
  if not ((select typical_age_low = 1 and typical_age_high = 3 from wine_archetypes where name = 'A typical Petit Chablis')) then raise exception 'post-state: A typical Petit Chablis age'; end if;
